from fastapi import FastAPI
from pydantic import BaseModel

app = FastAPI()

# Define the schema for inventory updates
class InventoryUpdate(BaseModel):
    sku: str
    quantity: int

# Endpoint validates incoming JSON against the model
@app.post("/inventory")
def update_inventory(item: InventoryUpdate):
    return {"status": "success", "sku": item.sku}
